blocks.value:
@layer tokens {
  :root {
    /* Color primitives */
    --color-blue-500: oklch(55% 0.2 260);
    --color-gray-100: oklch(96% 0.005 260);
    --color-gray-900: oklch(20% 0.02 260);

    /* Semantic aliases */
    --color-text: var(--color-gray-900);
    --color-bg: var(--color-gray-100);
    --color-accent: var(--color-blue-500);

    /* Spacing scale */
    --space-xs: 0.25rem;
    --space-sm: 0.5rem;
    --space-md: 1rem;
    --space-lg: 2rem;
    --space-xl: 4rem;

    /* Typography */
    --font-body: system-ui, sans-serif;
    --font-mono: 'SF Mono', 'Fira Code', monospace;
    --font-size-sm: 0.875rem;
    --font-size-base: 1rem;
    --font-size-lg: 1.25rem;
  }
}

@layer reset, tokens, base, layout, components, pages;

@import '_reset.css' layer(reset);
@import '_tokens.css' layer(tokens);
@import '_base.css' layer(base);
@import '_layout.css' layer(layout);
@import '_components.css' layer(components);

children.value:
@layer components {
  /* Author your own custom element with the same pattern: */
  my-banner {
    display: block;
    padding: var(--size-m);
    border-radius: var(--radius-m);
    border-inline-start: 4px solid var(--banner-color);
    background: var(--banner-bg);
  }

  my-banner[data-variant='warning'] {
    --banner-color: var(--color-warning);
    --banner-bg: oklch(from var(--color-warning) l c h / 0.1);
  }
}
